mapper.select:
/* [판독결과] 조회 - selectWkGroupList */ SELECT W.WK_ID AS wkId, W.WK_NM AS wkNm, W.DOC_TYP_NM AS docTypNm FROM ocuoc_ocrwf_m W
W.WK_ID = #{wkId}
ORDER BY W.REG_DT DESC, W.WK_ID DESC

/* [판독결과] 조회 - selectWkFormList */ SELECT L.LEFRM_ID AS lefrmId, L.LEFRM_NM AS lefrmNm, L.DOC_ID AS formId, M.WK_ID AS wkId, L.REG_STA_CD AS regStaCd FROM ocuoc_ocrwl_l M JOIN ocuoc_lefrm_m L ON L.LEFRM_ID = M.LEFRM_ID
M.WK_ID = #{wkId}
ORDER BY L.LEFRM_ID
